import React,{useState} from "react";
import {createRoot} from "react-dom/client";
import "../../src/styles.css";
import {Button} from "../../src/shared/ui";
import {FieldRenderer} from "../../src/lowcode/FieldRenderer";
import {FieldDesigner} from "../../src/lowcode/FieldDesigner";
import {AdvancedFieldSettings} from "../../src/lowcode/AdvancedFieldSettings";
import {validateValues,type TableSchema} from "../../src/lowcode/field-model";
const image="10000000-0000-4000-8000-000000000001",text="10000000-0000-4000-8000-000000000002",table="10000000-0000-4000-8000-000000000003",row="10000000-0000-4000-8000-000000000004";
const calls:string[]=[],originalFetch=window.fetch;(window as unknown as {advancedFixture:unknown}).advancedFixture={calls};
window.fetch=async(input,init)=>{const url=new URL(String(input),location.origin),path=url.pathname;const json=(value:unknown)=>new Response(JSON.stringify(value),{status:200,headers:{"Content-Type":"application/json"}});if(path==="/api/v1/me")return json({id:"10000000-0000-4000-8000-000000000099",displayName:"验收成员",username:"fixture",enabled:true});if(path.startsWith("/api/v1/lc/files/")){calls.push(path);const id=path.split("/")[5],content=path.endsWith("/content");if(id===image)return content?new Response(Uint8Array.from(atob("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j5qUAAAAASUVORK5CYII="),c=>c.charCodeAt(0)),{headers:{"Content-Type":"image/png","Content-Disposition":"attachment; filename=fixture.png"}}):json({id,name:"现场图片.png",contentType:"image/png",size:68});if(id===text)return content?new Response("合同备注\n<script>window.unsafePreview=true</script>",{headers:{"Content-Type":"text/plain","Content-Disposition":"attachment; filename=note.txt"}}):json({id,name:"备注.txt",contentType:"text/plain",size:100});}return originalFetch(input,init);};
const definition:TableSchema={name:"字段参数验收",description:"文本格式、子表操作与文件入口",fields:[
 {id:"code",label:"业务编码",type:"text",required:true,advancedConfig:{inputMode:"numeric",textPreset:"digits"}},
 {id:"phone",label:"联系电话",type:"phone",advancedConfig:{phoneType:"landlineCN",inputMode:"tel"}},
 {id:"line",label:"说明分隔线",type:"divider",advancedConfig:{divider:{style:"dashed",color:"#7c3aed",thickness:3}}},
 {id:"lines",label:"费用明细",type:"subtable",width:12,advancedConfig:{subtable:{allowCopy:true,density:"compact"}},subtableConfig:{maxRows:6,fields:[{id:"item",label:"项目名称",type:"text"},{id:"amount",label:"金额",type:"number"},{id:"total",label:"计算值",type:"formula",formulaConfig:{expression:{op:"MUL",left:{op:"FIELD",fieldId:"amount"},right:{op:"CONST",value:2}}}},{id:"locked",label:"系统值",type:"text",readOnly:true}]}},
 {id:"image",label:"现场图片",type:"image",advancedConfig:{media:{capture:"camera",allowDesktopUpload:false,preview:false,download:false}}},
 {id:"attachment",label:"备注附件",type:"attachment",advancedConfig:{media:{preview:true,download:false}}}
]};
const initial={code:"00123",phone:"010-12345678-123",lines:[{id:row,values:{item:"资料服务",amount:200,total:400,locked:"保留系统值"}}],image:[image],attachment:[text]};
function Fixture(){const [schema,setSchema]=useState(definition),[values,setValues]=useState<Record<string,unknown>>(initial),[baseline,setBaseline]=useState<Record<string,unknown>>(initial),[selected,setSelected]=useState("lines"),[errors,setErrors]=useState<Record<string,string>>({}),[designer,setDesigner]=useState(false);const field=schema.fields.find(field=>field.id===selected)!;
 return <main className="mx-auto max-w-6xl space-y-5 p-4 sm:p-6"><div className="flex flex-wrap items-center gap-2"><Button onClick={()=>setDesigner(!designer)}>{designer?"返回字段填写":"打开真实设计器"}</Button><Button variant="outline" onClick={()=>setBaseline(structuredClone(values))}>保存当前作为基线</Button><Button variant="outline" onClick={()=>setErrors(validateValues(schema,values,true,{mode:"edit",existing:baseline}))}>校验字段</Button></div>{designer?<FieldDesigner value={schema} onChange={setSchema} directory={{people:[],units:[],positions:[]}}/>:<div className="grid min-w-0 gap-5 lg:grid-cols-[1fr_320px]"><FieldRenderer schema={schema} value={values} originalValue={baseline} mode="edit" onChange={value=>{setValues(value);setErrors({});}} errors={errors} directory={{people:[],units:[],positions:[]}} fileContext={{tableId:table}}/><aside className="min-w-0 space-y-4 rounded-xl border border-border p-4"><label className="block space-y-2 text-sm">参数字段<select aria-label="参数字段" value={selected} onChange={event=>setSelected(event.target.value)} className="block w-full rounded-lg border border-border bg-background p-2">{schema.fields.map(field=><option key={field.id} value={field.id}>{field.label}</option>)}</select></label><AdvancedFieldSettings field={field} disabled={false} onChange={patch=>setSchema(current=>({...current,fields:current.fields.map(item=>item.id===selected?{...item,...patch}:item)}))}/></aside></div>}<pre data-testid="values" className="overflow-auto rounded-xl bg-muted p-3 text-xs">{JSON.stringify(values,null,2)}</pre><pre data-testid="errors" className="text-xs text-destructive">{JSON.stringify(errors,null,2)}</pre></main>;
}
const root=createRoot(document.getElementById("root")!);root.render(<Fixture/>);if(import.meta.hot)import.meta.hot.dispose(()=>{root.unmount();window.fetch=originalFetch;});
